#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minOperations(vector<int>& nums) {
        int m0 = 0, m1 = 0;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            int p = (nums[i] % 2 + 2) % 2;
            if (p != (i % 2)) m0++;
            if (p != ((i + 1) % 2)) m1++;
        }
        return min(m0, m1);
    }
};

class Solution {
    public int minOperations(int[] nums) {
        int m0 = 0, m1 = 0;
        for (int i = 0; i < nums.length; i++) {
            int p = (nums[i] % 2 + 2) % 2;
            if (p != (i % 2)) m0++;
            if (p != ((i + 1) % 2)) m1++;
        }
        return Math.min(m0, m1);
    }
}

